import React from 'react';
import '../styles/comicbooksmodal.css'; 

function ComicBooksModal({ isOpen, onClose, comics }) {
  if (!isOpen) return null;

  return (
    <div className="modal">
      {/* Close button and other modal structures */}
      <div>
        <h2>Comics</h2>
        {comics.map(comic => (
          <div key={comic.id}>
            <h3>{comic.title}</h3>
            {/* Other comic details like description, images, etc. */}
          </div>
        ))}
      </div>
      <button onClick={onClose}>Close</button>
    </div>
  );
}

export default ComicBooksModal;
